sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// run this to check if a Buddy Profile is actually attached to the schedule
    if (!current.x_travel_buddy_app_u_buddy_profile.nil()) {

        // database query on the Schedule table
        var grSchedule = new GlideRecord('cmn_schedule');

        //Search for any existing schedule where the Guide Profile matches the one we are trying to insert
        grSchedule.addQuery('x_travel_buddy_app_u_buddy_profile', current.x_travel_buddy_app_u_buddy_profile);
        grSchedule.query();

        // 4. If the database finds a match, abort
        if (grSchedule.hasNext()) {

            // 5. Show a red error message to the user on the screen
            gs.addErrorMessage('Action aborted: This Travel Buddy already has an active calendar. A guide can only have one master schedule container.');

            // 6. Stop the database from saving the record
            current.setAbortAction(true);
        }
    }

})(current, previous);
